<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('materials') ?></h1><div class="grid"><section class="card"><h2><?= View::t('new_material') ?></h2><form method="post" action="<?= View::e($basePath) ?>/materials"><?= View::csrf() ?><label><?= View::t('material') ?><input name="material_type" list="material-types" required placeholder="PLA"><datalist id="material-types"><option>PLA</option><option>PETG</option><option>ASA</option><option>ABS</option><option>PC</option><option>PA</option><option>TPU</option><option>PVA</option></datalist></label><label><?= View::t('manufacturer') ?><input name="manufacturer"></label><label><?= View::t('commercial_name') ?><input name="commercial_name"></label><div class="grid"><label><?= View::t('color') ?><input name="color_name" required></label><label>HEX<input name="color_hex" type="color" value="#f15a24"></label></div><label><?= View::t('diameter') ?> (mm)<input name="diameter_mm" type="number" step="0.01" value="1.75"></label><button><?= View::t('save') ?></button></form></section>
<section><div class="table-wrap"><table><thead><tr><th><?= View::t('material') ?></th><th><?= View::t('manufacturer') ?></th><th><?= View::t('color') ?></th><th>Ø</th><th></th></tr></thead><tbody><?php foreach($materials as $m): $hex=preg_match('/^#[0-9A-Fa-f]{6}$/',(string)$m['color_hex'])?$m['color_hex']:'#d0d5dd'; ?><tr><td><strong><?= View::e($m['material_type']) ?></strong><br><small><?= View::e($m['commercial_name']) ?></small></td><td><?= View::e($m['manufacturer_name']) ?></td><td><input class="color-swatch" type="color" value="<?= View::e($hex) ?>" disabled> <?= View::e($m['color_name']) ?></td><td><?= View::e($m['diameter_mm']) ?> mm</td><td><?php if(in_array($app->auth()->user()['role'],['admin','manager'],true)): ?><form method="post" action="<?= View::e($basePath) ?>/materials/<?= View::e($m['id']) ?>/delete"><?= View::csrf() ?><button class="link-button"><?= View::t('delete') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
